21	/** Tenta extrair peso e unidade do nome do produto (ex: "PASTA 25 KG" → {peso:25, unidade:'kg'}) */
22	function autoDetectPeso(nome: string | null): { peso: number; unidade: string } | null {
23	  if (!nome) return null;
24	  const m = nome.match(/(\d+(?:[.,]\d+)?)\s*(KG|G|L|ML|UN|UNIDADE|PACK)\b/i);
25	  if (!m) return null;
26	  const peso = Number(m[1].replace(',', '.'));
27	  if (!Number.isFinite(peso) || peso <= 0) return null;
28	  let unidade = m[2].toLowerCase();
29	  if (unidade === 'unidade') unidade = 'un';
30	  return { peso, unidade };
31	}
32	
33	const fmtBRL = (n: number) =>
34	  n.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
35	
36	const fmtDate = (d?: string | null) => {
37	  if (!d) return '—';
38	  try { return new Date(d).toLocaleDateString('pt-BR'); } catch { return d; }
39	};
