41	interface NFFull {
42	  id: number;
43	  fornecedor: string | null;
44	  numero_nota: string | null;
45	  valor_total: number | null;
46	  data_nota: string | null;
47	  is_esboco: boolean;
48	}
49	interface NFItemFull {
50	  id: number;
51	  nota_id: number;
52	  nome_produto: string | null;
53	  quantidade: number | null;
54	  valor_unitario: number | null;
55	  subtotal: number | null;
56	  insumo_id: number | null;
57	  peso_unitario: number | null;
58	  unidade_base: string | null;
59	}
60	
61	interface EditNFDialogProps {
62	  open: boolean;
63	  nfId: number | null;
64	  insumos: RawInsumo[];
65	  onClose: () => void;
66	  onSaved: () => void; // mantido por compat — não usado em modo read-only
67	}
68	
69	/**
70	 * Visualizador de NF (READ-ONLY).
71	 * Não permite editar — pra mudar uma NF real, ir na página de NFs.
72	 * A unidade de conversão é configurada NO INSUMO, não aqui.
73	 */
74	export function EditNFDialog({ open, nfId, insumos, onClose }: EditNFDialogProps) {
75	  const [loading, setLoading] = useState(false);
76	  const [nf, setNF] = useState<NFFull | null>(null);
77	  const [items, setItems] = useState<NFItemFull[]>([]);
78	  const navigate = useNavigate();
79	
80	  useEffect(() => {
81	    if (!open || nfId == null) {
82	      setNF(null);
83	      setItems([]);
84	      return;
85	    }
86	    setLoading(true);
87	    (async () => {
88	      const [nfRes, itensRes] = await Promise.all([
89	        supabase
90	          .from('notas_fiscais')
91	          .select('id, fornecedor, numero_nota, valor_total, data_nota, is_esboco')
92	          .eq('id', nfId)
93	          .single(),
94	        supabase
95	          .from('itens_nota_fiscal')
96	          .select('id, nota_id, nome_produto, quantidade, valor_unitario, subtotal, insumo_id, peso_unitario, unidade_base')
97	          .eq('nota_id', nfId)
98	          .order('id'),
99	      ]);
100	      if (nfRes.error) {
101	        toast.error('Erro ao carregar NF');
102	        setLoading(false);
103	        return;
104	      }
105	      setNF(nfRes.data as NFFull);
106	      setItems((itensRes.data ?? []) as NFItemFull[]);
107	      setLoading(false);
108	    })();
109	  }, [open, nfId]);
110	
111	  if (!open) return null;
112	
113	  const totalReal = items.reduce(
114	    (s, it) =>
115	      s + (Number(it.subtotal) || (Number(it.quantidade) || 0) * (Number(it.valor_unitario) || 0)),
116	    0
117	  );
118	
119	  const isEsboco = nf?.is_esboco === true;
120	
121	  return (
122	    <Dialog open={open} onOpenChange={(o) => !o && onClose()}>
123	      <DialogContent className="max-w-xl max-h-[88vh] flex flex-col">
124	        <DialogHeader>
125	          <DialogTitle className="flex items-center gap-2">
126	            <Receipt className={`h-4 w-4 ${isEsboco ? 'text-orange-500' : 'text-blue-500'}`} />
127	            {isEsboco ? 'NF Esboço' : 'Nota Fiscal'}
128	            <span className="text-[10px] uppercase tracking-wider text-muted-foreground font-normal">
129	              · somente leitura
130	            </span>
131	          </DialogTitle>
132	        </DialogHeader>
133	
134	        {loading ? (
135	          <div className="flex items-center justify-center py-12">
136	            <Loader2 className="h-6 w-6 animate-spin text-blue-500" />
137	          </div>
138	        ) : !nf ? (
139	          <div className="py-12 text-center text-sm text-muted-foreground">NF não encontrada.</div>
140	        ) : (
141	          <div className="flex-1 overflow-y-auto space-y-3 py-2">
142	            {isEsboco && (
143	              <div className="rounded-lg bg-orange-50 dark:bg-orange-950/30 p-2.5 text-[11px] flex items-start gap-2">
144	                <Sparkles className="h-3.5 w-3.5 text-orange-500 shrink-0 mt-0.5" />
145	                <p className="text-orange-700 dark:text-orange-300">
146	                  NF em modo esboço (planejamento). Vai virar NF real quando lançada de verdade.
147	                </p>
148	              </div>
149	            )}
150	
151	            {/* Cabeçalho NF */}
152	            <div className="grid grid-cols-2 gap-3 rounded-lg border border-border p-3 bg-slate-50/50 dark:bg-slate-800/30">
153	              <div>
154	                <p className="text-[10px] uppercase tracking-wider text-muted-foreground">Fornecedor</p>
155	                <p className="text-sm font-semibold truncate">{nf.fornecedor ?? '—'}</p>
156	              </div>
157	              <div>
158	                <p className="text-[10px] uppercase tracking-wider text-muted-foreground">Número NF</p>
159	                <p className="text-sm font-mono">{nf.numero_nota ?? '—'}</p>
160	              </div>
161	              <div>
162	                <p className="text-[10px] uppercase tracking-wider text-muted-foreground">Data</p>
163	                <p className="text-sm flex items-center gap-1">
164	                  <Calendar className="h-3 w-3 text-muted-foreground" />
165	                  {fmtDate(nf.data_nota)}
166	                </p>
167	              </div>
168	              <div>
169	                <p className="text-[10px] uppercase tracking-wider text-muted-foreground">Valor total</p>
170	                <p className="text-sm font-bold tabular-nums text-blue-700 dark:text-blue-300">
171	                  {fmtBRL(totalReal || Number(nf.valor_total) || 0)}
172	                </p>
173	              </div>
174	            </div>
175	
176	            {/* Items da NF — read only */}
177	            <div>
178	              <p className="text-[10px] uppercase tracking-wider text-muted-foreground font-bold px-1 mb-1.5">
179	                Itens da NF ({items.length})
180	              </p>
181	              <div className="space-y-1.5">
182	                {items.length === 0 && (
183	                  <div className="text-center py-6 text-sm text-muted-foreground">
184	                    Sem itens nesta NF.
185	                  </div>
186	                )}
187	                {items.map((it, idx) => (
188	                  <NFItemRow
189	                    key={it.id}
190	                    item={it}
191	                    insumo={it.insumo_id ? insumos.find((i) => i.id === it.insumo_id) ?? null : null}
192	                    onUpdate={(patch) => {
193	                      setItems((prev) =>
194	                        prev.map((x, i) => (i === idx ? { ...x, ...patch } : x))
195	                      );
196	                    }}
197	                  />
198	                ))}
199	              </div>
200	            </div>
201	
202	            <div className="rounded-lg bg-blue-50/50 dark:bg-blue-950/20 border border-blue-200 dark:border-blue-800/40 p-2.5 text-[11px] text-blue-700 dark:text-blue-300">
203	              💡 <strong>Pra ajustar unidades (kg/g, pack/un, etc.)</strong>: clique no node do <strong>Insumo</strong> no canvas
204	              → bloco "Unidades & Conversão" → Editar. A NF fica intocada.
205	            </div>
206	          </div>
207	        )}
208	
209	        <DialogFooter className="border-t border-border pt-3">
210	          {!isEsboco && nf && (
211	            <Button
