214	              className="mr-auto"
215	            >
216	              <ExternalLink className="mr-1.5 h-3.5 w-3.5" />
217	              Abrir na página de NFs
218	            </Button>
219	          )}
220	          <Button data-mia-action="close" variant="outline" onClick={onClose}>Fechar</Button>
221	        </DialogFooter>
222	      </DialogContent>
223	    </Dialog>
224	  );
225	}
