227	/* ──────────────────────────────────────────────────────────────
228	   NFItemRow — uma linha (item) da NF, com config de peso/unidade
229	   ────────────────────────────────────────────────────────────── */
230	
231	interface NFItemRowProps {
232	  item: NFItemFull;
233	  insumo: RawInsumo | null;
234	  onUpdate: (patch: Partial<NFItemFull>) => void;
235	}
236	
237	function NFItemRow({ item, insumo, onUpdate }: NFItemRowProps) {
238	  const [editing, setEditing] = useState(false);
239	  const [peso, setPeso] = useState<number>(Number(item.peso_unitario) || 0);
240	  const [unidade, setUnidade] = useState<string>(item.unidade_base ?? 'kg');
241	  const [saving, setSaving] = useState(false);
242	
243	  useEffect(() => {
244	    setPeso(Number(item.peso_unitario) || 0);
245	    setUnidade(item.unidade_base ?? 'kg');
246	  }, [item.peso_unitario, item.unidade_base]);
247	
248	  const qty = Number(item.quantidade) || 0;
249	  const valorUnit = Number(item.valor_unitario) || 0;
250	  const subtotal = Number(item.subtotal) || qty * valorUnit;
251	  const pesoTotal = peso > 0 ? qty * peso : 0;
252	  const precoEfetivo = peso > 0 ? valorUnit / peso : 0;
253	
254	  const handleAutoDetect = () => {
255	    const det = autoDetectPeso(item.nome_produto);
256	    if (det) {
257	      setPeso(det.peso);
258	      setUnidade(det.unidade);
259	      toast.success(`Detectei: ${det.peso} ${det.unidade}`);
260	    } else {
261	      toast.error('Não consegui detectar — informe manualmente');
262	    }
263	  };
264	
265	  const handleSave = async () => {
266	    setSaving(true);
267	    try {
268	      const { error } = await supabase
269	        .from('itens_nota_fiscal')
270	        .update({ peso_unitario: peso > 0 ? peso : null, unidade_base: unidade })
271	        .eq('id', item.id);
272	      if (error) throw error;
273	      toast.success('Peso configurado — preço do insumo sincronizado');
274	      onUpdate({ peso_unitario: peso > 0 ? peso : null, unidade_base: unidade });
275	      setEditing(false);
276	    } catch (err) {
277	      toast.error(err instanceof Error ? err.message : 'Erro ao salvar');
278	    } finally {
279	      setSaving(false);
280	    }
281	  };
282	
283	  return (
284	    <div className="rounded-lg border border-border p-3 bg-white dark:bg-slate-900 space-y-2">
285	      {/* Linha topo: nome + subtotal */}
286	      <div className="flex items-start justify-between gap-2">
287	        <div className="flex-1 min-w-0">
288	          <p className="text-sm font-medium leading-snug">{item.nome_produto ?? '—'}</p>
289	          <p className="text-[10px] text-muted-foreground mt-0.5 tabular-nums">
290	            {qty} × {fmtBRL(valorUnit)}
291	          </p>
292	        </div>
293	        <div className="text-right shrink-0">
294	          <p className="text-base font-bold tabular-nums text-emerald-700 dark:text-emerald-300">
295	            {fmtBRL(subtotal)}
296	          </p>
297	          <p className="text-[9px] text-muted-foreground">total pago</p>
298	        </div>
299	      </div>
300	
301	      {/* Config peso/unidade */}
302	      <div className="rounded-md bg-amber-50 dark:bg-amber-950/30 border border-amber-200 dark:border-amber-800/40 p-2 text-[11px]">
303	        {!editing ? (
304	          <div className="flex items-center justify-between gap-2">
305	            {peso > 0 ? (
306	              <div>
307	                <p className="text-amber-700 dark:text-amber-300">
308	                  📦 Cada unidade = <strong>{peso} {unidade}</strong>
309	                </p>
310	                <p className="text-[10px] text-emerald-700 dark:text-emerald-300 tabular-nums">
311	                  ⇒ {qty} × {peso}{unidade} = <strong>{pesoTotal} {unidade}</strong> total · {fmtBRL(precoEfetivo)}/{unidade}
312	                </p>
313	              </div>
314	            ) : (
315	              <p className="text-orange-700 dark:text-orange-300">
316	                ⚠ Configure o peso por unidade pra calcular R$/{unidade} correto
317	              </p>
318	            )}
319	            <button
320	              onClick={() => setEditing(true)}
321	              className="text-[10px] text-amber-700 dark:text-amber-300 font-bold flex items-center gap-1 hover:underline"
322	            >
323	              <Pencil className="h-2.5 w-2.5" />
324	              {peso > 0 ? 'Editar' : 'Configurar'}
325	            </button>
326	          </div>
327	        ) : (
328	          <div className="space-y-2">
329	            <div className="grid grid-cols-3 gap-2 items-end">
330	              <div>
331	                <Label className="text-[9px] text-muted-foreground">Peso/un</Label>
332	                <Input data-mia-field="peso"
333	                  type="number" min={0} step="any"
334	                  className="h-7 text-xs"
335	                  value={peso || ''}
336	                  onChange={(e) => setPeso(e.target.value)}
337	                />
338	              </div>
339	              <div>
340	                <Label className="text-[9px] text-muted-foreground">Unidade</Label>
341	                <Select value={unidade} onValueChange={setUnidade}>
342	                  <SelectTrigger data-mia-filter="unidade" className="h-7 text-xs"><SelectValue /></SelectTrigger>
343	                  <SelectContent>
344	                    {UNIDADES_BASE_NF.map((u) => <SelectItem key={u} value={u}>{u}</SelectItem>)}
345	                  </SelectContent>
346	                </Select>
347	              </div>
348	              <button
349	                onClick={handleAutoDetect}
350	                className="h-7 px-2 rounded text-[10px] bg-blue-500 hover:bg-blue-600 text-white flex items-center justify-center gap-1"
351	                title="Auto-detectar do nome do produto"
352	              >
353	                <Wand2 className="h-3 w-3" />
354	                Auto
355	              </button>
356	            </div>
357	            {peso > 0 && (
358	              <p className="text-[10px] tabular-nums text-emerald-700 dark:text-emerald-300">
359	                Preview: {qty} × {peso}{unidade} = <strong>{pesoTotal} {unidade}</strong> · {fmtBRL(precoEfetivo)}/{unidade}
360	              </p>
361	            )}
362	            <div className="flex gap-1 justify-end">
363	              <button
364	                onClick={() => { setEditing(false); setPeso(Number(item.peso_unitario) || 0); setUnidade(item.unidade_base ?? 'kg'); }}
365	                className="text-[10px] text-muted-foreground hover:text-foreground px-2"
366	                disabled={saving}
367	              >
368	                Cancelar
369	              </button>
370	              <button
371	                onClick={handleSave}
372	                disabled={saving}
373	                className="text-[10px] bg-amber-500 hover:bg-amber-600 text-white px-2 py-0.5 rounded flex items-center gap-1"
374	              >
375	                {saving ? <Loader2 className="h-2.5 w-2.5 animate-spin" /> : <Check className="h-2.5 w-2.5" />}
376	                Salvar
377	              </button>
378	            </div>
379	          </div>
380	        )}
381	      </div>
382	
383	      {/* Status atrelagem */}
384	      {insumo ? (
385	        <p className="text-[10px] text-emerald-600 dark:text-emerald-400 flex items-center gap-1">
386	          🔗 Atrelado: <strong>{insumo.nome}</strong>
387	        </p>
388	      ) : (
389	        <p className="text-[10px] text-muted-foreground italic">
390	          Não atrelado — arraste a NF no canvas até o insumo correspondente
391	        </p>
392	      )}
393	    </div>
394	  );
395	}
