232	interface NFItemRowProps {
233	  item: NFItemFull;
234	  insumo: RawInsumo | null;
235	  onUpdate: (patch: Partial<NFItemFull>) => void;
236	  onChanged: () => void;
237	}
238	
239	function NFItemRow({ item, insumo, onUpdate, onChanged }: NFItemRowProps) {
240	  const [editing, setEditing] = useState(false);
241	  const [peso, setPeso] = useState<number>(Number(item.peso_unitario) || 0);
242	  const [unidade, setUnidade] = useState<string>(item.unidade_base ?? 'kg');
243	  const [saving, setSaving] = useState(false);
244	  const [desatrelando, setDesatrelando] = useState(false);
245	
246	  useEffect(() => {
247	    setPeso(Number(item.peso_unitario) || 0);
248	    setUnidade(item.unidade_base ?? 'kg');
249	  }, [item.peso_unitario, item.unidade_base]);
250	
251	  const qty = Number(item.quantidade) || 0;
252	  const valorUnit = Number(item.valor_unitario) || 0;
253	  const subtotal = Number(item.subtotal) || qty * valorUnit;
254	  const pesoTotal = peso > 0 ? qty * peso : 0;
255	  const precoEfetivo = peso > 0 ? valorUnit / peso : 0;
256	
257	  const handleAutoDetect = () => {
258	    const det = autoDetectPeso(item.nome_produto);
259	    if (det) {
260	      setPeso(det.peso);
261	      setUnidade(det.unidade);
262	      toast.success(`Detectei: ${det.peso} ${det.unidade}`);
263	    } else {
264	      toast.error('Não consegui detectar — informe manualmente');
265	    }
266	  };
267	
268	  const handleSave = async () => {
269	    setSaving(true);
270	    try {
271	      const { error } = await supabase
272	        .from('itens_nota_fiscal')
273	        .update({ peso_unitario: peso > 0 ? peso : null, unidade_base: unidade })
274	        .eq('id', item.id);
275	      if (error) throw error;
276	      toast.success('Peso configurado — preço do insumo sincronizado');
277	      onUpdate({ peso_unitario: peso > 0 ? peso : null, unidade_base: unidade });
278	      setEditing(false);
279	    } catch (err) {
280	      toast.error(err instanceof Error ? err.message : 'Erro ao salvar');
281	    } finally {
282	      setSaving(false);
283	    }
284	  };
285	
286	  const handleDesatrelar = async () => {
287	    setDesatrelando(true);
288	    try {
289	      const { error } = await supabase
290	        .from('itens_nota_fiscal')
291	        .update({ insumo_id: null })
292	        .eq('id', item.id);
293	      if (error) throw error;
294	      toast.success('NF desatrelada do insumo — preço recalculado');
295	      onUpdate({ insumo_id: null });
296	      onChanged();
297	    } catch (err) {
298	      toast.error(err instanceof Error ? err.message : 'Erro ao desatrelar');
299	    } finally {
300	      setDesatrelando(false);
301	    }
302	  };
303	
304	  return (
305	    <div className="rounded-lg border border-border p-3 bg-white dark:bg-slate-900 space-y-2">
306	      {/* Linha topo: nome + subtotal */}
307	      <div className="flex items-start justify-between gap-2">
308	        <div className="flex-1 min-w-0">
309	          <p className="text-sm font-medium leading-snug">{item.nome_produto ?? '—'}</p>
310	          <p className="text-[10px] text-muted-foreground mt-0.5 tabular-nums">
311	            {qty} × {fmtBRL(valorUnit)}
312	          </p>
313	        </div>
314	        <div className="text-right shrink-0">
315	          <p className="text-base font-bold tabular-nums text-emerald-700 dark:text-emerald-300">
316	            {fmtBRL(subtotal)}
317	          </p>
318	          <p className="text-[9px] text-muted-foreground">total pago</p>
319	        </div>
320	      </div>
321	
322	      {/* Config peso/unidade */}
323	      <div className="rounded-md bg-amber-50 dark:bg-amber-950/30 border border-amber-200 dark:border-amber-800/40 p-2 text-[11px]">
324	        {!editing ? (
325	          <div className="flex items-center justify-between gap-2">
326	            {peso > 0 ? (
327	              <div>
328	                <p className="text-amber-700 dark:text-amber-300">
329	                  📦 Cada unidade = <strong>{peso} {unidade}</strong>
330	                </p>
331	                <p className="text-[10px] text-emerald-700 dark:text-emerald-300 tabular-nums">
332	                  ⇒ {qty} × {peso}{unidade} = <strong>{pesoTotal} {unidade}</strong> total · {fmtBRL(precoEfetivo)}/{unidade}
333	                </p>
334	              </div>
335	            ) : (
336	              <p className="text-orange-700 dark:text-orange-300">
337	                ⚠ Configure o peso por unidade pra calcular R$/{unidade} correto
338	              </p>
339	            )}
340	            <button
341	              onClick={() => setEditing(true)}
342	              className="text-[10px] text-amber-700 dark:text-amber-300 font-bold flex items-center gap-1 hover:underline"
343	            >
344	              <Pencil className="h-2.5 w-2.5" />
345	              {peso > 0 ? 'Editar' : 'Configurar'}
346	            </button>
347	          </div>
348	        ) : (
349	          <div className="space-y-2">
350	            <div className="grid grid-cols-3 gap-2 items-end">
351	              <div>
352	                <Label className="text-[9px] text-muted-foreground">Peso/un</Label>
353	                <Input data-mia-field="peso"
354	                  type="number" min={0} step="any"
355	                  className="h-7 text-xs"
356	                  value={peso || ''}
357	                  onChange={(e) => setPeso(e.target.value)}
358	                />
359	              </div>
360	              <div>
361	                <Label className="text-[9px] text-muted-foreground">Unidade</Label>
362	                <Select value={unidade} onValueChange={setUnidade}>
363	                  <SelectTrigger data-mia-filter="unidade" className="h-7 text-xs"><SelectValue /></SelectTrigger>
364	                  <SelectContent>
365	                    {UNIDADES_BASE_NF.map((u) => <SelectItem key={u} value={u}>{u}</SelectItem>)}
366	                  </SelectContent>
367	                </Select>
368	              </div>
369	              <button
370	                onClick={handleAutoDetect}
371	                className="h-7 px-2 rounded text-[10px] bg-blue-500 hover:bg-blue-600 text-white flex items-center justify-center gap-1"
372	                title="Auto-detectar do nome do produto"
373	              >
374	                <Wand2 className="h-3 w-3" />
375	                Auto
376	              </button>
377	            </div>
378	            {peso > 0 && (
379	              <p className="text-[10px] tabular-nums text-emerald-700 dark:text-emerald-300">
380	                Preview: {qty} × {peso}{unidade} = <strong>{pesoTotal} {unidade}</strong> · {fmtBRL(precoEfetivo)}/{unidade}
381	              </p>
382	            )}
383	            <div className="flex gap-1 justify-end">
384	              <button
385	                onClick={() => { setEditing(false); setPeso(Number(item.peso_unitario) || 0); setUnidade(item.unidade_base ?? 'kg'); }}
386	                className="text-[10px] text-muted-foreground hover:text-foreground px-2"
387	                disabled={saving}
388	              >
389	                Cancelar
390	              </button>
391	              <button
392	                onClick={handleSave}
393	                disabled={saving}
394	                className="text-[10px] bg-amber-500 hover:bg-amber-600 text-white px-2 py-0.5 rounded flex items-center gap-1"
395	              >
396	                {saving ? <Loader2 className="h-2.5 w-2.5 animate-spin" /> : <Check className="h-2.5 w-2.5" />}
397	                Salvar
398	              </button>
399	            </div>
400	          </div>
401	        )}
402	      </div>
403	
404	      {/* Status atrelagem */}
405	      {insumo ? (
406	        <div className="flex items-center justify-between gap-2">
407	          <p className="text-[10px] text-emerald-600 dark:text-emerald-400 flex items-center gap-1">
408	            🔗 Atrelado: <strong>{insumo.nome}</strong>
409	          </p>
410	          <button
411	            onClick={handleDesatrelar}
412	            disabled={desatrelando}
413	            className="text-[10px] text-red-500 hover:text-red-700 dark:hover:text-red-400 font-medium flex items-center gap-0.5 hover:underline disabled:opacity-50"
414	            title="Desatrelar esta NF do insumo"
415	          >
416	            {desatrelando
417	              ? <Loader2 className="h-2.5 w-2.5 animate-spin" />
418	              : <Unlink className="h-2.5 w-2.5" />}
419	            Desatrelar
420	          </button>
421	        </div>
422	      ) : (
423	        <p className="text-[10px] text-muted-foreground italic">
424	          Não atrelado — arraste a NF no canvas até o insumo correspondente
425	        </p>
426	      )}
427	    </div>
428	  );
429	}
